+// Probe a HiWonder MentorPi rosbridge: list topics and sample /odom.
+// Usage: node ws_probe.js <ip> [topic]
+const ip = process.argv[2];
+const topic = process.argv[3] || "/odom";
+const url = `ws://${ip}:9090`;
+
+const ws = new WebSocket(url);
+let got = 0;
+const t0 = Date.now();
+
+const done = (code) => {
+  try { ws.close(); } catch {}
+  process.exit(code);
+};
+
+ws.onopen = () => {
+  console.log(`[${ip}] connected ${url}`);
+  ws.send(JSON.stringify({ op: "subscribe", topic, type: "nav_msgs/msg/Odometry" }));
+  ws.send(JSON.stringify({ op: "subscribe", topic, type: "nav_msgs/Odometry" }));
+};
+
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.op === "publish" && m.topic === topic) {
+    const p = m.msg.pose.pose.position;
+    const v = m.msg.twist.twist.linear;
+    console.log(`[${ip}] ${topic} #${++got} pos=(${p.x.toFixed(3)},${p.y.toFixed(3)}) vel=(${v.x.toFixed(3)},${v.y.toFixed(3)})`);
+    if (got >= 3) done(0);
+  } else if (m.op === "status" && m.level === "error") {
+    console.log(`[${ip}] status error:`, m.msg);
