+// Call a rosapi service over rosbridge.
+// Usage: node rosapi.js <ip> <service> [argsJson] [timeoutMs]
+const ip = process.argv[2];
+const service = process.argv[3] || "/rosapi/nodes";
+const args = process.argv[4] ? JSON.parse(process.argv[4]) : {};
+const timeout = Number(process.argv[5] || 8000);
+
+const ws = new WebSocket(`ws://${ip}:9090`);
+const id = `call_service:${service}:1`;
+
+ws.onopen = () => {
+  ws.send(JSON.stringify({ op: "call_service", id, service, args }));
+};
+
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  console.log(`[${ip}] ${m.op}:`, JSON.stringify(m.values ?? m).slice(0, 4000));
+  if (m.op === "service_response") finish(m.result === false ? 1 : 0);
+};
+
+ws.onerror = (e) => {
+  console.log(`[${ip}] ws error`, e.message || e.type);
+  finish(2);
+};
+
+function finish(code) {
+  try { ws.close(); } catch {}
+  process.exit(code);
+}
+
+setTimeout(() => { console.log(`[${ip}] timeout calling ${service}`); finish(3); }, timeout);
