+// Subscribe to a topic over rosbridge and report the first N messages.
+// Usage: node ws_sub.js <ip> <topic> <type> [count] [ms]
+const [ip, topic, type] = process.argv.slice(2, 5);
+const count = Number(process.argv[5] || 3);
+const ms = Number(process.argv[6] || 10000);
+const ws = new WebSocket(`ws://${ip}:9090`);
+let got = 0;
+
+const finish = (code) => { try { ws.close(); } catch {} process.exit(code); };
+
+ws.onopen = () => {
+  console.log(`[${ip}] connected, subscribing ${topic} (${type})`);
+  ws.send(JSON.stringify({ op: "subscribe", topic, type }));
+};
+
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.op === "publish") {
+    got++;
+    if (got <= count) console.log(`[${ip}] ${topic} #${got} ${JSON.stringify(m.msg).slice(0, 200)}`);
+    if (got === count) finish(0);
+  } else if (m.op === "status" && m.level === "error") {
+    console.log(`[${ip}] status error: ${JSON.stringify(m.msg)}`);
+  }
+};
+
+ws.onerror = (e) => { console.log(`[${ip}] ws error ${e.message || e.type}`); finish(2); };
+setTimeout(() => { console.log(`[${ip}] ${topic}: ${got} messages in ${ms}ms`); finish(got ? 0 : 3); }, ms);
