+// Drive one or more MentorPi cars forward through their rosbridge servers.
+// Usage: node drive.js --ips 192.168.43.6,192.168.43.8 --speed 0.1 --hold 1.0
+// Publishes geometry_msgs/Twist to /controller/cmd_vel while watching /odom.
+
+const argv = process.argv.slice(2);
+const arg = (name, def) => {
+  const i = argv.indexOf(`--${name}`);
+  return i >= 0 ? argv[i + 1] : def;
+};
+
+const ips = arg("ips", "").split(",").map((s) => s.trim()).filter(Boolean);
+const speed = Math.min(Math.max(Number(arg("speed", 0.1)), -0.3), 0.3);
+const holdS = Math.min(Math.max(Number(arg("hold", 1.0)), 0.1), 10);
+const rate = Math.min(Math.max(Number(arg("rate", 20)), 1), 50);
+const topic = arg("topic", "/controller/cmd_vel");
+
+if (!ips.length) {
+  console.error("need --ips");
+  process.exit(2);
+}
+
+const clamp = (v, a, b) => Math.min(Math.max(v, a), b);
+const tw = (v) => JSON.stringify({
+  linear: { x: v, y: 0, z: 0 },
+  angular: { x: 0, y: 0, z: 0 },
+});
+
+const cars = new Map();
+for (const ip of ips) cars.set(ip, { ip, ws: null, ready: false, odom: null, odom0: null, maxV: 0, n: 0 });
+
+const connect = (car) =>
+  new Promise((resolve) => {
+    const ws = new WebSocket(`ws://${car.ip}:9090`);
+    car.ws = ws;
+    ws.onopen = () => {
+      ws.send(JSON.stringify({ op: "subscribe", topic: "/odom", type: "nav_msgs/msg/Odometry" }));
+      car.ready = true;
+      resolve(true);
+    };
+    ws.onerror = () => resolve(false);
+    ws.onmessage = (ev) => {
+      const m = JSON.parse(ev.data);
+      if (m.op !== "publish") return;
+      const p = m.msg.pose.pose.position;
+      car.n++;
+      car.odom = { x: p.x, y: p.y };
+      if (!car.odom0) car.odom0 = { ...car.odom };
+      car.maxV = Math.max(car.maxV, Math.abs(m.msg.twist.twist.linear.x));
+    };
+    setTimeout(() => resolve(car.ready), 4000);
+  });
+
+const pub = (car, v) => {
+  if (!car.ready || car.ws.readyState !== 1) return;
+  car.ws.send(JSON.stringify({ op: "publish", topic, type: "geometry_msgs/msg/Twist", msg: JSON.parse(tw(v)) }));
+};
+
+const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
+
+(async () => {
+  console.log(`targets: ${ips.join(", ")}  speed=${speed} m/s  hold=${holdS}s  rate=${rate}Hz  topic=${topic}`);
+  await Promise.all([...cars.values()].map(connect));
+  for (const c of cars.values()) console.log(`  ${c.ip}: rosbridge ${c.ready ? "ok" : "FAILED"}, odom msgs=${c.n}`);
+
+  await sleep(600); // let odom baseline settle
+  const base = [...cars.values()].map((c) => ({ ip: c.ip, o: c.odom ? { ...c.odom } : null }));
+
+  const t0 = Date.now();
+  const period = 1000 / rate;
+  while (Date.now() - t0 < holdS * 1000) {
+    const tt = Date.now() - t0;
+    // tiny ramp on the first 150 ms so the wheels engage smoothly
+    const v = tt < 150 ? speed * (tt / 150) : speed;
+    for (const c of cars.values()) pub(c, v);
+    await sleep(period);
+  }
+  const tStop = Date.now();
+
+  // explicit stop burst
+  for (let i = 0; i < 15; i++) {
+    for (const c of cars.values()) pub(c, 0);
+    await sleep(period);
+  }
+  console.log(`stop burst done (${Date.now() - tStop} ms after last motion command)`);
+
+  await sleep(400);
+  for (const c of cars.values()) {
+    const b = base.find((x) => x.ip === c.ip)?.o;
+    if (!b || !c.odom) {
+      console.log(`  ${c.ip}: odom unavailable (msgs=${c.n})`);
+      continue;
+    }
+    const dx = c.odom.x - b.x;
+    const dy = c.odom.y - b.y;
+    console.log(
+      `  ${c.ip}: dx=${dx.toFixed(4)} m  dy=${dy.toFixed(4)} m  dist=${Math.hypot(dx, dy).toFixed(4)} m  maxV=${c.maxV.toFixed(3)} m/s  odom@${c.n}msgs`
+    );
+  }
+  for (const c of cars.values()) { try { c.ws.close(); } catch {} }
+  setTimeout(() => process.exit(0), 200);
+})();
