+// Send a short forward pulse over rosbridge while watching that car's own /imu
+// to see whether the motors actually engaged.
+// Usage: node imu_pulse.js <ip> [speed] [holdMs]
+const ip = process.argv[2];
+const speed = Number(process.argv[3] || 0.12);
+const holdMs = Number(process.argv[4] || 1200);
+const ws = new WebSocket(`ws://${ip}:9090`);
+const samples = [];
+let phase = "idle-before";
+let started = 0;
+
+const tw = (v) => JSON.stringify({
+  linear: { x: v, y: 0, z: 0 },
+  angular: { x: 0, y: 0, z: 0 },
+});
+const pub = (v) => ws.send(JSON.stringify({ op: "publish", topic: "/controller/cmd_vel", type: "geometry_msgs/msg/Twist", msg: JSON.parse(tw(v)) }));
+
+ws.onopen = () => {
+  ws.send(JSON.stringify({ op: "subscribe", topic: "/imu", type: "sensor_msgs/msg/Imu" }));
+  console.log(`[${ip}] connected; idle baseline 1.5 s, then ${holdMs} ms forward @ ${speed} m/s`);
+  started = Date.now();
+
+  setTimeout(() => {
+    phase = "moving";
+    const t0 = Date.now();
+    const iv = setInterval(() => {
+      if (Date.now() - t0 >= holdMs) {
+        clearInterval(iv);
+        phase = "idle-after";
+        const j = setInterval(() => {}, 1000);
+        let k = 0;
+        const stopIv = setInterval(() => {
+          pub(0);
+          if (++k >= 20) {
+            clearInterval(stopIv);
+            clearInterval(j);
+            setTimeout(report, 900);
+          }
+        }, 50);
+        return;
+      }
+      pub(speed);
+    }, 50);
+  }, 1500);
+};
+
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.op !== "publish") return;
+  const a = m.msg.linear_acceleration;
+  const g = m.msg.angular_velocity;
+  samples.push({
+    t: Date.now() - started,
+    phase,
+    an: Math.hypot(a.x, a.y, a.z),
+    gn: Math.hypot(g.x, g.y, g.z),
+  });
+};
+
+const stats = (rows, key) => {
+  if (!rows.length) return "n/a";
+  const v = rows.map((r) => r[key]);
+  const mean = v.reduce((s, x) => s + x, 0) / v.length;
+  const sd = Math.sqrt(v.reduce((s, x) => s + (x - mean) ** 2, 0) / v.length);
+  return `n=${v.length} mean=${mean.toFixed(3)} sd=${sd.toFixed(3)} max=${Math.max(...v).toFixed(3)}`;
+};
+
+function report() {
+  const before = samples.filter((r) => r.phase === "idle-before");
+  const during = samples.filter((r) => r.phase === "moving");
+  const after = samples.filter((r) => r.phase === "idle-after");
+  console.log(`[${ip}] accel |a|: before  ${stats(before, "an")}`);
+  console.log(`[${ip}] accel |a|: during  ${stats(during, "an")}`);
+  console.log(`[${ip}] accel |a|: after   ${stats(after, "an")}`);
+  console.log(`[${ip}] gyro  |w|: before  ${stats(before, "gn")}`);
+  console.log(`[${ip}] gyro  |w|: during  ${stats(during, "gn")}`);
+  console.log(`[${ip}] gyro  |w|: after   ${stats(after, "gn")}`);
+  try { ws.close(); } catch {}
+  process.exit(0);
+}
+
+setTimeout(() => { console.log("hard timeout"); report(); }, 15000);
