+const watcher = new WebSocket(`ws://${watchIp}:9090`);
+const samples = [];
+let phase = "idle-before";
+let t0 = 0;
+
+const tw = (v) => JSON.stringify({ linear: { x: v, y: 0, z: 0 }, angular: { x: 0, y: 0, z: 0 } });
