+  publisher.readyState === 1 &&
+  publisher.send(JSON.stringify({ op: "publish", topic: "/controller/cmd_vel", type: "geometry_msgs/msg/Twist", msg: JSON.parse(tw(v)) }));
+
+const stats = (rows, key) => {
+  if (!rows.length) return "n/a";
+  const v = rows.map((r) => r[key]);
+  const mean = v.reduce((s, x) => s + x, 0) / v.length;
+  const sd = Math.sqrt(v.reduce((s, x) => s + (x - mean) ** 2, 0) / v.length);
+  return `n=${v.length} mean=${mean.toFixed(3)} sd=${sd.toFixed(3)} max=${Math.max(...v).toFixed(3)}`;
+};
+
+let ready = 0;
+const maybeStart = () => {
+  if (++ready < 2) return;
+  t0 = Date.now();
