+    else console.log(`  odom moved: dx=${(e.x - b.x).toFixed(4)} m dy=${(e.y - b.y).toFixed(4)} m  (samples ${samples.length})`);
+  } else {
+    console.log(`  |a| before: ${stats(before, "an")}`);
+    console.log(`  |a| during: ${stats(during, "an")}`);
+    console.log(`  |a| after : ${stats(after, "an")}`);
