+#!/usr/bin/env node
+/**
+ * MentorPi 双车（或多车）同步控制脚本
+ *
+ * 通过每台车自带的 rosbridge（ws://<ip>:9090）向 /controller/cmd_vel 发布
+ * geometry_msgs/Twist，用同一事件循环给所有车同时下发指令，并读取 /odom 回报
+ * 实测位移与起步时间差。
+ *
+ * 用法示例：
+ *   node mentorpi_drive.js --ips 192.168.43.6,192.168.43.8 --dist 0.5
+ *   node mentorpi_drive.js --ips 192.168.43.6,192.168.43.8 --speed 0.2 --hold 2
+ *   node mentorpi_drive.js --ips 192.168.43.6,192.168.43.8 --turn 90 --speed 0.5
+ *   node mentorpi_drive.js --ips 192.168.43.6 --dist 0.3 --dry-run
+ *
+ * 参数：
+ *   --ips    逗号分隔的车 IP（必填，按顺序即 6 号车、8 号车）
+ *   --speed  线速度 m/s，默认 0.15（限幅 0.3）
+ *   --hold   持续秒数，默认 1.5（限幅 10）
+ *   --dist   目标距离 m（给了就用 dist/speed 反推 hold，覆盖 --hold）
+ *   --turn   原地转向角度（度，正数左转）；给了就 turn 模式，忽略 dist
+ *   --rate   发布频率 Hz，默认 20
+ *   --dry-run 只连接、订阅 /odom、打印目标，不发任何运动指令
+ *
+ * 安全性：指令结束后会以 20Hz 连续补发约 0.75s 的零速，确保底盘停住。
+ */
+const argv = process.argv.slice(2);
+const arg = (name, def) => {
