+// Fetch one LaserScan via rosbridge, save JSON, print stats.
+// Usage: node get_scan.js <ip> [outfile]
+const ip = process.argv[2];
+const out = process.argv[3] || `work/scan_${ip}.json`;
+const ws = new WebSocket(`ws://${ip}:9090`);
+let done = false;
+
+ws.onopen = () => ws.send(JSON.stringify({ op: "subscribe", topic: "/scan_raw", type: "sensor_msgs/msg/LaserScan" }));
+
+ws.onmessage = async (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.op !== "publish" || done) return;
+  done = true;
+  const s = m.msg;
+  const ranges = s.ranges;
+  const valid = ranges.filter((r) => r > s.range_min && r < s.range_max && Number.isFinite(r));
+  const stats = {
+    ip,
+    frame_id: s.header.frame_id,
+    n_points: ranges.length,
+    angle_min_deg: (s.angle_min * 180 / Math.PI).toFixed(2),
+    angle_max_deg: (s.angle_max * 180 / Math.PI).toFixed(2),
+    angle_increment_deg: (s.angle_increment * 180 / Math.PI).toFixed(3),
+    range_min: s.range_min,
+    range_max: s.range_max,
+    valid_points: valid.length,
+    min_range: valid.length ? Math.min(...valid).toFixed(3) : null,
+    max_range: valid.length ? Math.max(...valid).toFixed(3) : null,
+    mean_range: valid.length ? (valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(3) : null,
+  };
+  require("fs").writeFileSync(out, JSON.stringify(m.msg));
+  console.log(JSON.stringify(stats, null, 2));
+  try { ws.close(); } catch {}
+  process.exit(0);
+};
+
+ws.onerror = (e) => { console.log(`[${ip}] ws error ${e.message || e.type}`); process.exit(2); };
+setTimeout(() => { console.log(`[${ip}] timeout, no scan received`); process.exit(3); }, 15000);
