+ws.onopen = () => ws.send(JSON.stringify({ op: "subscribe", topic: "/scan_raw", type: "sensor_msgs/msg/LaserScan" }));
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.op !== "publish") return;
+  scans.push(m.msg.ranges);
+  if (m.msg.angle_increment) incDeg = (m.msg.angle_increment * 180) / Math.PI;
+  if (scans.length >= count) finish();
+};
+ws.onerror = () => process.exit(2);
