+function scoreAt(a, b, k) {
+  const n = Math.min(a.length, b.length);
+  let s = 0, c = 0;
+  for (let i = 0; i < n; i++) {
+    const j = (i + k + n) % n; // 当前扫描平移 k 个波束后与基线对齐
+    const x = a[i], y = b[j];
+    if (x === null || y === null) continue;
+    s += Math.abs(x - y); c++;
+  }
+  return c ? s / c : Infinity;
+}
+
