+async function move(dx, dy, speed = 0.12) {
+  const dist = Math.hypot(dx, dy);
+  if (dist < 0.002) return;
+  const holdS = dist / speed;
+  const period = 50;
+  const t0 = Date.now();
+  while (Date.now() - t0 < holdS * 1000) {
