+// Lidar-closed-loop straight-line motion for a MentorPi.
+// Estimates the car's true displacement/orientation change by matching live
+// LaserScan frames against a reference frame (polar least-squares matching),
+// then servos to a target displacement along the car's own forward axis.
+//
+// Usage: node lidar_move.js <ip> <forward_m> <backward_m> [tol_m] [tol_deg]
+//   e.g. node lidar_move.js 192.168.43.6 1.0 -2.0
+const ip = process.argv[2];
+const target1 = Number(process.argv[3]); // 第一段，正=前进
+const target2 = Number(process.argv[4]); // 第二段，负=后退
+const TOL = Number(process.argv[5] || 0.02);      // 位置容差 m
+const TOL_DEG = Number(process.argv[6] || 1.5);   // 朝向容差 度
+const INC = 0.015707963267948967;                 // 0.9 deg per beam
+const SPEED = 0.15;
+const RATE = 20;
+const PERIOD = 1000 / RATE;
+
+const ws = new WebSocket(`ws://${ip}:9090`);
+const scans = [];
+let odom = null;
+
+ws.onopen = () => {
+  ws.send(JSON.stringify({ op: "subscribe", topic: "/scan_raw", type: "sensor_msgs/msg/LaserScan" }));
+  ws.send(JSON.stringify({ op: "subscribe", topic: "/odom", type: "nav_msgs/msg/Odometry" }));
+};
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.op !== "publish") return;
+  if (m.topic === "/scan_raw") {
+    scans.push(m.msg.ranges);
+    if (scans.length > 8) scans.shift();
+  } else {
+    const p = m.msg.pose.pose.position, q = m.msg.pose.pose.orientation;
+    odom = {
+      x: p.x, y: p.y,
+      yaw: Math.atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z)),
+    };
+  }
+};
+
+const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
+const pub = (x, y, z) =>
+  ws.readyState === 1 &&
+  ws.send(JSON.stringify({
+    op: "publish", topic: "/controller/cmd_vel", type: "geometry_msgs/msg/Twist",
+    msg: { linear: { x, y, z: 0 }, angular: { x: 0, y: 0, z } },
+  }));
+
+async function freshScan(n = 2, waitMs = 400) {
+  await sleep(waitMs);
+  const s = scans.slice(-n);
+  return s.length ? s : null;
+}
+
+// 对参考帧做极坐标最小二乘匹配：R_i = S_{i+k} + p·u_i  (u_i 为参考系下的波束方向)
+function matchOne(ref, cur) {
+  const n = Math.min(ref.length, cur.length);
+  let best = null;
+  for (let k = -14; k <= 14; k++) {
+    let a11 = 0, a12 = 0, a22 = 0, b1 = 0, b2 = 0;
+    const rows = [];
+    for (let i = 0; i < n; i++) {
+      const j = (i + k + n) % n;
+      const r = ref[i], s = cur[j];
+      if (r === null || s === null || r === undefined || s === undefined) continue;
+      const d = r - s;
+      const a = i * INC;
+      const ux = Math.cos(a), uy = Math.sin(a);
+      a11 += ux * ux; a12 += ux * uy; a22 += uy * uy;
+      b1 += d * ux; b2 += d * uy;
+      rows.push({ d, ux, uy });
+    }
+    const det = a11 * a22 - a12 * a12;
+    if (rows.length < 50 || Math.abs(det) < 1e-9) continue;
+    const px = (b1 * a22 - b2 * a12) / det;
+    const py = (a11 * b2 - a12 * b1) / det;
+    const res = rows.map((o) => Math.abs(o.d - (px * o.ux + py * o.uy))).sort((x, y) => x - y);
+    const med = res[Math.floor(res.length / 2)];
+    if (!best || med < best.res) best = { dx: px, dy: py, k, res: med, n: rows.length };
+  }
+  return best;
+}
+
+// 多帧取中位数，抗噪
+function match(ref, curs) {
+  const est = curs.map((c) => matchOne(ref, c)).filter(Boolean);
+  if (!est.length) return null;
+  const med = (arr) => arr.sort((a, b) => a - b)[Math.floor(arr.length / 2)];
+  return {
+    dx: med(est.map((e) => e.dx)),
+    dy: med(est.map((e) => e.dy)),
+    k: med(est.map((e) => e.k)),
+    res: med(est.map((e) => e.res)),
+  };
+}
+
+async function driveFrom(vx, vy, wz, ms) {
+  const t0 = Date.now();
+  while (Date.now() - t0 < ms) {
+    const k = Math.min((Date.now() - t0) / 150, 1);
+    pub(vx * k, vy * k, wz * k);
+    await sleep(PERIOD);
+  }
+  for (let i = 0; i < 10; i++) { pub(0, 0, 0); await sleep(PERIOD); }
+}
+
+// 闭环：把小车位移伺服到 (tx, ty)（参考系坐标，沿轴向），同时压住朝向偏差
+async function servoTo(ref, u, tgtU, tgtV, label, maxIter = 40) {
+  let lastErr = Infinity;
+  for (let i = 1; i <= maxIter; i++) {
+    const s = await freshScan(2, 350);
+    const e = match(ref, s);
+    if (!e) { console.log("    匹配失败"); return null; }
+    // 位移分解到 前进轴 u 和其左法向 v
+    const dU = e.dx * u.x + e.dy * u.y;
+    const dV = e.dx * -u.y + e.dy * u.x;
+    const yawErr = -e.k * INC; // k>0 表示车体逆时针转（经验符号，见校准输出）
+    const eU = tgtU - dU, eV = tgtV - dV, eTh = yawErr;
+    const err = Math.hypot(eU, eV);
+    console.log(
+      `    ${label} 第${i}次: 前进方向 ${dU.toFixed(3)}m, 侧向 ${dV.toFixed(3)}m, 朝向 ${(yawErr * 180 / Math.PI).toFixed(1)}°, 匹配残差 ${e.res.toFixed(3)}m`
+    );
+    if (err <= TOL && Math.abs(yawErr) <= TOL_DEG * Math.PI / 180) return { dU, dV, yawErr, res: e.res };
+    if (err > lastErr + 0.02 && i > 4) { console.log("    误差发散，停止"); return { dU, dV, yawErr, res: e.res }; }
+    lastErr = err;
+    let vx = 0, vy = 0, wz = 0;
