+#!/usr/bin/env node
+/**
+ * MentorPi 远程部署工具（把 ROS 2 包/代码推到车上并编译）
+ *
+ * 原理：本机 ssh(OpenSSH) + tar 打包 → 直接解到车里的 Docker 容器 MentorPi
+ *      → 容器内 colcon build → 可选重启服务/启动节点
+ *
+ * 用法示例：
+ *   node deploy.js --check --ips 192.168.43.6,192.168.43.8
+ *   node deploy.js --src ./mentorpi_check --dest /home/ubuntu/ros2_ws/src/mentorpi_check --build --ips 192.168.43.6
+ *   node deploy.js --src ./mentorpi_check --dest ... --build --restart service --ips 192.168.43.6,192.168.43.8
+ *   node deploy.js --src ./mentorpi_check --dest ... --build --run "ros2 run mentorpi_check check_node" --ips 192.168.43.6
+ *
+ * 常用参数：
+ *   --ips        逗号分隔的车 IP（必填，除了 --check 之外）
+ *   --src        本机要部署的目录（默认取 --dest 的最后一段同名目录）
+ *   --dest       容器内目标路径（绝对路径）
+ *   --pkgs       要 colcon build 的包名（默认取 --dest 的末段）
+ *   --build      部署后编译
+ *   --restart    service | none（service = sudo systemctl restart start_node.service）
+ *   --run        部署后后台启动的命令（在容器里执行）
+ *   --backup     部署前备份原目录（默认开启；--no-backup 关闭）
+ *   --dry-run    只打印计划，不实际执行
+ *   --key        SSH 私钥路径（默认 ~/.ssh/id_codex_mentorpi）
+ *
+ * 安全说明：
+ *   - 只覆盖 --dest 指定目录，不动系统其它部分
+ *   - 覆盖前默认把原目录打包到容器内 /home/ubuntu/deploy_backup/<名字>-<时间>.tgz
+ *   - 回滚：docker exec MentorPi tar xzf <备份> -C <dest 的父目录>
+ */
+const { spawn } = require("child_process");
+const os = require("os");
+const path = require("path");
+
+const argv = process.argv.slice(2);
+const has = (n) => argv.includes(`--${n}`);
+const val = (n, d) => {
+  const i = argv.indexOf(`--${n}`);
+  return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d;
+};
+
+const KEY = val("key", path.join(os.homedir(), ".ssh", "id_codex_mentorpi"));
+const CONTAINER = val("container", "MentorPi");
+const ips = String(val("ips", "")).split(",").map((s) => s.trim()).filter(Boolean);
+const src = val("src", null);
+const dest = val("dest", null);
+const pkgs = val("pkgs", dest ? dest.replace(/[\\/]+$/, "").split(/[\\/]/).pop() : null);
+const doCheck = has("check");
+const doBuild = has("build");
+const restart = val("restart", "none");
+const runCmd = val("run", null);
+const backup = !has("no-backup");
+const dryRun = has("dry-run");
+
+const SSH_OPTS = [
+  "-i", KEY,
+  "-o", "BatchMode=yes",
+  "-o", "IdentitiesOnly=yes",
+  "-o", "StrictHostKeyChecking=accept-new",
+  "-o", "ConnectTimeout=15",
+];
+
+if (!ips.length) {
+  console.error("需要 --ips，例如 --ips 192.168.43.6,192.168.43.8");
+  process.exit(2);
+}
+if (!doCheck && (!src || !dest)) {
+  console.error("需要 --src 与 --dest（或用 --check 只做连通性检查）");
+  process.exit(2);
+}
+
+const run = (cmd, args, { input = null, quiet = false } = {}) =>
+  new Promise((resolve) => {
+    if (dryRun) {
+      console.log(`    [dry-run] ${cmd} ${args.join(" ")}`);
+      return resolve({ code: 0, out: "", err: "" });
+    }
+    const p = spawn(cmd, args, { stdio: ["pipe", "pipe", "pipe"] });
+    let out = "", err = "";
+    p.stdout.on("data", (d) => { out += d; if (!quiet) process.stdout.write(d); });
+    p.stderr.on("data", (d) => { err += d; if (!quiet) process.stderr.write(d); });
+    p.on("error", (e) => resolve({ code: 127, out, err: String(e) }));
+    p.on("close", (code) => resolve({ code, out, err }));
+    if (input) p.stdin.end(input); else p.stdin.end();
+  });
+
+const ssh = (ip, remoteCmd, opts) => run("ssh", [...SSH_OPTS, `pi@${ip}`, remoteCmd], opts);
+const dockerExec = (ip, args, opts) =>
+  ssh(ip, `docker exec ${args}`, opts);
+
+(async () => {
