+      allOk = false;
+      continue;
+    }
+    const ps = await ssh(ip, `docker ps --format '{{.Names}}' | grep -x ${CONTAINER} || true`, { quiet: true });
+    const containerUp = ps.out.trim() === CONTAINER;
