+    if (!containerUp) { allOk = false; continue; }
+
+    if (doCheck) {
+      const info = await ssh(ip, `docker exec -u ubuntu ${CONTAINER} bash -lc 'echo -n "domain="; printenv ROS_DOMAIN_ID; echo -n "liday_type="; grep -h "^export LIDAR_TYPE" /home/ubuntu/ros2_ws/.typerc 2>/dev/null; ls -d /home/ubuntu/ros2_ws/src >/dev/null && echo "src: OK"'`, { quiet: true });
+      console.log(`  ${info.out.trim().split("\n").join("  ")}`);
+      continue;
+    }
+
+    // 2) 备份目标目录
+    if (backup) {
+      const ts = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
+      const bk = `/home/ubuntu/deploy_backup/${pkgs}-${ts}.tgz`;
+      const r = await ssh(ip, `docker exec -u ubuntu ${CONTAINER} bash -lc "mkdir -p /home/ubuntu/deploy_backup && if [ -d ${dest} ]; then tar czf ${bk} -C ${dest} . && echo backed-up:${bk}; else echo no-existing-dir; fi"`, { quiet: true });
+      console.log(`  备份: ${r.out.trim()}`);
+    }
+
+    // 3) 推送代码（tar 流经 ssh 直接解到容器内）
+    console.log(`  推送 ${src} → ${dest}`);
+    const tarPath = process.platform === "win32" ? "tar.exe" : "tar";
+    const unpack = `docker exec -i -u ubuntu ${CONTAINER} bash -lc "mkdir -p ${dest} && tar xzf - -C ${dest}"`;
+    const push = await new Promise((resolve) => {
+      if (dryRun) { console.log(`    [dry-run] tar -czf - -C ${src} . | ssh pi@${ip} '${unpack}'`); return resolve(0); }
+      const t = spawn(tarPath, ["-czf", "-", "-C", src, "."]);
+      const s = spawn("ssh", [...SSH_OPTS, `pi@${ip}`, unpack], { stdio: ["pipe", "inherit", "inherit"] });
+      t.stdout.pipe(s.stdin);
+      let done = 0;
+      const finish = (code) => { if (++done === 2) resolve(code); };
+      t.on("close", (c) => { if (c) console.log(`  ✗ tar 退出码 ${c}`); finish(c); });
+      s.on("close", (c) => finish(c));
+    });
+    console.log(push === 0 ? "  ✓ 代码已推送" : `  ✗ 推送失败（码 ${push}）`);
+    if (push !== 0) { allOk = false; continue; }
+
+    // 4) 编译
+    if (doBuild) {
+      console.log(`  编译 ${pkgs} ...`);
+      const b = await ssh(ip, `docker exec -u ubuntu -w /home/ubuntu/ros2_ws ${CONTAINER} bash -lc "source /opt/ros/humble/setup.bash && colcon build --packages-select ${pkgs} --symlink-install"`);
+      if (b.code !== 0) { console.log(`  ✗ 编译失败`); allOk = false; continue; }
+      console.log(`  ✓ 编译完成`);
+    }
+
+    // 5) 重启服务 / 启动节点
+    if (restart === "service") {
